const input = $input.first().json;
const family_upserts = [];
const keyword_upserts = [];
const need_upserts = [];
for (const family of input.families || []) {
  family_upserts.push({ family_id: family.family_id, taxonomy_version: input.taxonomy_version, label: family.label, reference_tension: family.reference_tension, priority: family.priority, valid_from: input.valid_from, valid_to: input.valid_to || null });
  for (const keyword of family.keywords || []) keyword_upserts.push({ keyword_key: `${input.taxonomy_version}:${family.family_id}:${keyword}`, taxonomy_version: input.taxonomy_version, family_id: family.family_id, keyword, normalized_keyword: keyword, valid_from: input.valid_from, valid_to: input.valid_to || null });
  for (const need of family.training_needs || []) need_upserts.push({ need_key: `${input.taxonomy_version}:${family.family_id}:${need.need_id}`, taxonomy_version: input.taxonomy_version, family_id: family.family_id, need_id: need.need_id, label: need.label, confidence: need.confidence, valid_from: input.valid_from, valid_to: input.valid_to || null });
}
return [{ json: { ...input, family_upserts, keyword_upserts, training_need_upserts: need_upserts } }];
